+/// Where the path crosses x = 0 highest.
+fn top_at_x0(p: &camcraft_app::cl::Toolpath) -> f64 {
+    p.moves
+        .iter()
+        .filter_map(|m| {
+            let (a, b) = (m.from, m.to);
+            ((a.x <= 0.0) != (b.x <= 0.0)).then(|| a.y + (b.y - a.y) * (0.0 - a.x) / (b.x - a.x))
+        })
+        .fold(f64::NEG_INFINITY, f64::max)
+}
