+        Point2::new(-0.5, -0.1),
+        Point2::new(0.5, -0.1),
+        Point2::new(10.0, -5.0),
+        Point2::new(10.0, 5.0),
+        Point2::new(0.5, 0.1),
+        Point2::new(-0.5, 0.1),
+        Point2::new(-10.0, 5.0),
